    code: ContextErrorCode,
    check: &str,
    path: Option<Utf8PathBuf>,
    message: &str,
) -> ImplementationContextFailure {
    ImplementationContextFailure {
        contract_id: CONTEXT_CONTRACT_ID.to_owned(),
        status: wisp_model::ContextFailureStatus::Error,
        error: ContextError { code, check: check.to_owned(), path, message: message.to_owned() },
    }
}

